INSERT INTO `faqs` (`id`, `service_id`, `city_id`, `kecamatan_id`, `question`, `answer`, `order`, `status`, `created_at`, `updated_at`) VALUES (1, 1, 51, NULL, 'Apakah sertifikat Ahli K3 Umum di Malang resmi Kemnaker RI?', 'Ya, seluruh sertifikat Ahli K3 Umum diterbitkan langsung oleh Kementerian Ketenagakerjaan RI (Kemnaker RI) lengkap dengan SKP (Surat Keputusan Penunjukan) dan Lisensi K3 resmi nasional.', 1, 'published', '2026-09-08 09:02:42', '2026-09-08 09:02:42');
INSERT INTO `faqs` (`id`, `service_id`, `city_id`, `kecamatan_id`, `question`, `answer`, `order`, `status`, `created_at`, `updated_at`) VALUES (2, 1, 51, NULL, 'Di mana lokasi sentra praktik sertifikasi K3 di wilayah Malang?', 'Sentra praktik diselenggarakan di fasilitas laboratorium mitra resmi kawasan Lowokwaru dan sentra industri Karanglo Malang dengan peralatan simulator standar Kemnaker RI.', 2, 'published', '2026-09-08 09:02:42', '2026-09-08 09:02:42');
INSERT INTO `faqs` (`id`, `service_id`, `city_id`, `kecamatan_id`, `question`, `answer`, `order`, `status`, `created_at`, `updated_at`) VALUES (3, NULL, 51, 1, 'Apakah perusahaan di Lowokwaru bisa meminta sesi In-House Training K3?', 'Sangat bisa. Kami menyediakan in-house training langsung di fasilitas industri, rumah sakit, maupun pabrik di kawasan Lowokwaru dengan jadwal yang disesuaikan kebutuhan shift kerja.', 1, 'published', '2026-09-08 09:02:42', '2026-09-08 09:02:42');

